<?php require_once __DIR__.'/../config/db.php';$pageTitle='All Students';require __DIR__.'/includes/admin_layout_start.php';$rows=[];try{$rows=db()->query("SELECT id,full_name,email,phone,address,is_suspended,created_at FROM users WHERE role='student' ORDER BY created_at DESC")->fetchAll();}catch(Throwable $e){} ?>
<h1 class="h3 mb-1">All students</h1><p class="text-secondary mb-4">Manage registered student access.</p><?php if($m=flash('admin_success')):?><div class="alert alert-success"><?=e($m)?></div><?php endif;?><div class="admin-table table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Address</th><th>Registered</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold"><?=e($r['full_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['address'] ?: '—')?></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td><td><span class="badge <?= $r['is_suspended']?'text-bg-danger':'text-bg-success'?> status-badge"><?= $r['is_suspended']?'Suspended':'Active'?></span></td><td><form method="post" action="actions.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_student"><input type="hidden" name="id" value="<?=e((string)$r['id'])?>"><input type="hidden" name="redirect" value="all_students.php"><button class="btn btn-sm <?= $r['is_suspended']?'btn-brand':'btn-outline-danger'?>"><?= $r['is_suspended']?'Activate':'Suspend'?></button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center text-secondary py-5">No students found.</td></tr><?php endif;?></tbody></table></div><?php require __DIR__.'/includes/admin_layout_end.php'; ?>
